import{_ as o,c as t,o as r,aj as a}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"Interface: DocumentQueryOptions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/primitive-functions/api/interfaces/DocumentQueryOptions.md","filePath":"reference/primitive-functions/api/interfaces/DocumentQueryOptions.md"}'),c={name:"reference/primitive-functions/api/interfaces/DocumentQueryOptions.md"};function n(d,e,i,s,l,h){return r(),t("div",null,[...e[0]||(e[0]=[a('<p><a href="./../README.html"><strong>primitive-functions</strong></a></p><hr><p><a href="./../globals.html">primitive-functions</a> / DocumentQueryOptions</p><h1 id="interface-documentqueryoptions" tabindex="-1">Interface: DocumentQueryOptions <a class="header-anchor" href="#interface-documentqueryoptions" aria-label="Permalink to “Interface: DocumentQueryOptions”">​</a></h1><p>The options a document model read takes: a filter object (or its JSON), a page size, a cursor.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="cursor" tabindex="-1">cursor? <a class="header-anchor" href="#cursor" aria-label="Permalink to “cursor?”">​</a></h3><blockquote><p><code>optional</code> <strong>cursor?</strong>: <code>string</code></p></blockquote><hr><h3 id="documentformat" tabindex="-1">documentFormat? <a class="header-anchor" href="#documentformat" aria-label="Permalink to “documentFormat?”">​</a></h3><blockquote><p><code>optional</code> <strong>documentFormat?</strong>: <code>1</code> | <code>2</code> | <code>3</code></p></blockquote><p>The document format you expect. When it disagrees with the format the platform resolved, the call is refused with a 409 DOCUMENT_FORMAT_MISMATCH rather than answered out of the wrong tables. Usually stated once on the handle, as ctx.doc(id, { documentFormat: 2 }), rather than per read.</p><hr><h3 id="filter" tabindex="-1">filter? <a class="header-anchor" href="#filter" aria-label="Permalink to “filter?”">​</a></h3><blockquote><p><code>optional</code> <strong>filter?</strong>: <code>string</code> | <code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;</p></blockquote><hr><h3 id="include" tabindex="-1">include? <a class="header-anchor" href="#include" aria-label="Permalink to “include?”">​</a></h3><blockquote><p><code>optional</code> <strong>include?</strong>: <code>string</code> | <a href="./DocumentIncludeSpec.html"><code>DocumentIncludeSpec</code></a>[]</p></blockquote><p>Related records to answer with each record on a db3 (a format-3 document), as <code>_related</code>; ignored on a format-1 document. Nested to depth 3. The response, <code>_related</code> included, is at most 8 MiB and a <code>hasMany</code> spec reads at most 1,000 related rows per request; past either the read is refused with a 400 DB3_PAGE_TOO_LARGE, never cut.</p><hr><h3 id="limit" tabindex="-1">limit? <a class="header-anchor" href="#limit" aria-label="Permalink to “limit?”">​</a></h3><blockquote><p><code>optional</code> <strong>limit?</strong>: <code>number</code></p></blockquote><p>Records per page: 100 when omitted, at most 10,000; a larger value is refused with a 400 naming the maximum, never clamped. A page also ends before the record that would take it past 8 MiB (the sum of each record&#39;s JSON in UTF-8 bytes; the envelope is not counted), answering <code>hasMore: true</code> and a <code>nextCursor</code> that continues from the last record returned; a single record larger than 8 MiB is answered alone. A page that fills <code>limit</code> exactly also answers <code>hasMore: true</code>; loop on <code>hasMore</code> rather than counting rows.</p><hr><h3 id="sort" tabindex="-1">sort? <a class="header-anchor" href="#sort" aria-label="Permalink to “sort?”">​</a></h3><blockquote><p><code>optional</code> <strong>sort?</strong>: <code>Record</code>&lt;<code>string</code>, <code>1</code> | <code>-1</code>&gt;</p></blockquote><p>The order of the rows: each field maps to 1 (ascending) or -1 (descending), and key order is precedence, as in { createdAt: -1 }. <code>id</code> breaks ties unless you name it. <code>limit</code> and <code>cursor</code> apply to the ordered rows; pass the same sort with a <code>cursor</code>, since a cursor from another sort is refused with a 400.</p>',27)])])}const m=o(c,[["render",n]]);export{p as __pageData,m as default};
